//
// diff: 1 = 学部前半 / 2 = 学部後半 / 3 = 院試 / 4 = 博士（鬼）。第1章は各 20 問
// ch:   出題する章（第1章 = 立体化学・SN1/SN2/E1/E2・転位、第2章 = カルボニル化学、第3章 = ラジカル・芳香族、第4章 = ペリ環状反応・対称と鏡像、第5章 = 合成戦略・不斉合成と光学分割）
// tag:  ボス戦などで使う分類。第2章 keto = カルボニルへの付加など / enol = エノール・エノラート
//       第3章 radical = ラジカル反応 / arom = 芳香族
//       第4章 peri = ペリ環状反応 / mirror = 対称・点群・鏡像・光学分割
//       第5章 synth = 合成戦略（逆合成・保護基・化学選択性・順序） / asym = 不斉合成と光学分割
// a:    正解の choices の添字（表示時に選択肢はシャッフルする）
