// cs:     選択肢を構造式で出すときの SMILES（null の選択肢は文字のまま）
// cl:     構造式の選択肢に添える注記（「ラセミ体」など）
// mols:   問題文に出てくる化合物の構造式 [[名前, SMILES], ...]（名前を添えて並べる）
// cm:     選択肢の化合物の構造式（名前といっしょに表示する。cs と違い、名前は隠さない）
// =============================================================
